/**
 * Filters ESLint results to error-severity messages only for edited files.
 *
 * @param {Array<{ filePath: string, messages: Array<{ severity: number, ruleId: string | null, line: number, message: string }>, ... }>} results
 * @param {Set<string>} editedFiles
 * @returns {Array<{ file: string, line: number, rule: string | null, message: string }>}.
 */
function blockingErrors(results, editedFiles) {
  const matched = new Set(editedFiles);
  const out = []

  for (const result of results) {
    const { filePath, messages } = result
    if (!matched.has(filePath)) continue
    for (const msg of messages) {
      if (msg.severity === 2) {
        out.push({
          file: filePath,
          line: msg.line,
          rule: msg.ruleId,
          message: msg.message,
        })
      }
    }
  }

  out.sort((a, b) => {
    if (a.file < b.file) return -1
    if (a.file > b.file) return 1
    return a.line - b.line
  })

  return out
}

